import React from 'react';
import { HTMLMotionProps, motion } from 'framer-motion';
import { hoverLift, reveal } from './motion';
import { card, cardHover } from './sections';
import { Spotlight, trackSpotlight } from './spotlight';

interface SpotlightCardProps extends Omit<HTMLMotionProps<'article'>, 'children'> {
  index?: number;
  innerClassName?: string;
  children: React.ReactNode;
}

// A card that reveals on scroll, lifts on hover and glows under the cursor.
const SpotlightCard: React.FC<SpotlightCardProps> = ({
  index = 0,
  className = '',
  innerClassName = '',
  children,
  ...rest
}) => (
  <motion.article
    {...reveal(index)}
    {...hoverLift}
    onMouseMove={trackSpotlight}
    className={`group relative overflow-hidden ${card} ${cardHover} ${className}`}
    {...rest}
  >
    <Spotlight />
    <div className={`relative h-full ${innerClassName}`}>{children}</div>
  </motion.article>
);

export default SpotlightCard;
