import React, { useRef } from 'react';
import { motion, useScroll, useSpring } from 'framer-motion';
import SectionHeading from './SectionHeading';
import TechTags from './TechTags';
import { splitMetrics } from './metrics';
import { reveal } from './motion';
import { card, chip, sectionAnchor } from './sections';
import { portfolio } from '../../data/portfolio';

// Highlights with their numbers in bold, so a skim picks up the impact.
const Highlight: React.FC<{ text: string }> = ({ text }) => (
  <li className="relative pl-5 text-sm leading-relaxed text-slate-600 before:absolute before:left-0 before:top-2 before:h-1.5 before:w-1.5 before:rounded-full before:bg-brand-500 dark:text-slate-400">
    {splitMetrics(text).map((part, index) =>
      part.metric ? (
        <strong key={index} className="font-semibold text-ink-900 dark:text-white">
          {part.text}
        </strong>
      ) : (
        <React.Fragment key={index}>{part.text}</React.Fragment>
      )
    )}
  </li>
);

const Experience: React.FC = () => {
  const timelineRef = useRef<HTMLDivElement>(null);
  // The timeline line draws itself as the section scrolls past.
  const { scrollYProgress } = useScroll({ target: timelineRef, offset: ['start 75%', 'end 60%'] });
  const lineScale = useSpring(scrollYProgress, { stiffness: 120, damping: 30, restDelta: 0.001 });

  return (
    <section id="experience" aria-labelledby="experience-title" className={sectionAnchor}>
      <SectionHeading
        id="experience-title"
        eyebrow="Career"
        title="Work history"
        subtitle="From junior engineer to senior lead, shipping production software since 2019."
      />
      <div ref={timelineRef} className="relative pl-8 md:pl-10">
        <span aria-hidden="true" className="absolute bottom-4 left-[9px] top-4 w-0.5 rounded-full bg-slate-200 dark:bg-white/10" />
        <motion.span
          aria-hidden="true"
          style={{ scaleY: lineScale }}
          className="absolute bottom-4 left-[9px] top-4 w-0.5 origin-top rounded-full bg-gradient-to-b from-brand-500 to-violet-500"
        />
        <ol className="space-y-6">
          {portfolio.experience.map((job) => {
            const isCurrent = job.end === null;
            return (
              <li key={job.company} className="relative">
                <span aria-hidden="true" className="absolute -left-8 top-8 flex h-5 w-5 items-center justify-center md:-left-10">
                  {isCurrent && (
                    <span className="absolute h-full w-full rounded-full bg-brand-400 opacity-60 motion-safe:animate-ping" />
                  )}
                  <span className="relative h-5 w-5 rounded-full border-4 border-surface-light bg-gradient-to-br from-brand-500 to-violet-500 dark:border-surface-dark" />
                </span>
                <motion.article {...reveal()} className={`p-6 md:p-8 ${card}`}>
                  <div className="flex flex-wrap items-start justify-between gap-3">
                    <div>
                      <h3 className="text-lg font-semibold text-ink-900 dark:text-white">{job.company}</h3>
                      <p className="mt-1 text-sm text-slate-500 dark:text-slate-400">
                        <span className="font-semibold text-brand-700 dark:text-brand-300">{job.role}</span>
                        {' · '}
                        {job.location}
                      </p>
                    </div>
                    <div className="flex flex-wrap items-center gap-2">
                      {isCurrent && (
                        <span className="rounded-full bg-emerald-50 px-3 py-1 text-xs font-semibold text-emerald-700 ring-1 ring-emerald-200 dark:bg-emerald-500/10 dark:text-emerald-300 dark:ring-emerald-500/30">
                          Current role
                        </span>
                      )}
                      <span className={chip}>{`${job.start} – ${job.end ?? 'Present'}`}</span>
                    </div>
                  </div>
                  <ul className="mt-5 space-y-2.5">
                    {job.highlights.map((line) => (
                      <Highlight key={line} text={line} />
                    ))}
                  </ul>
                  <TechTags label={`${job.company} tech stack`} items={job.stack} />
                </motion.article>
              </li>
            );
          })}
        </ol>
      </div>
    </section>
  );
};

export default Experience;
