import React from 'react';
import { motion } from 'framer-motion';
import {
  AcademicCapIcon,
  ArrowDownTrayIcon,
  ArrowRightIcon,
  BuildingLibraryIcon,
  MapPinIcon,
  SparklesIcon,
} from '@heroicons/react/24/outline';
import Avatar from './Avatar';
import CountUp from './CountUp';
import RotatingText from './RotatingText';
import { EASE } from './motion';
import { card, IconComponent, primaryButton, secondaryButton, sectionAnchor } from './sections';
import { portfolio } from '../../data/portfolio';

// The hero copy enters line by line.
const stagger = { hidden: {}, show: { transition: { staggerChildren: 0.1, delayChildren: 0.1 } } };
const rise = {
  hidden: { opacity: 0, y: 20 },
  show: { opacity: 1, y: 0, transition: { duration: 0.6, ease: EASE } },
};

const Backdrop: React.FC = () => (
  <div aria-hidden="true" className="pointer-events-none absolute inset-0">
    <div className="absolute inset-0 bg-dot-grid [background-size:22px_22px] dark:bg-dot-grid-dark" />
    <div className="absolute -right-16 -top-24 h-80 w-80 rounded-full bg-brand-400/25 blur-3xl motion-safe:animate-float dark:bg-brand-500/20" />
    <div className="absolute -bottom-24 right-48 h-72 w-72 rounded-full bg-violet-400/20 blur-3xl motion-safe:animate-float-delayed dark:bg-violet-500/15" />
  </div>
);

interface ProofBadgeProps {
  icon: IconComponent;
  text: string;
  className: string;
  delay: number;
}

// Glassy proof points that float beside the portrait. Decorative: the same
// facts appear in the stats and case studies.
const ProofBadge: React.FC<ProofBadgeProps> = ({ icon: Icon, text, className, delay }) => (
  <motion.div
    aria-hidden="true"
    initial={{ opacity: 0, scale: 0.8 }}
    animate={{ opacity: 1, scale: 1 }}
    transition={{ duration: 0.6, delay, ease: EASE }}
    className={`absolute z-10 hidden lg:block ${className}`}
  >
    <div className="flex items-center gap-2 rounded-2xl border border-white/60 bg-white/80 px-3 py-2 text-xs font-semibold text-ink-900 shadow-card-hover backdrop-blur motion-safe:animate-bob dark:border-white/10 dark:bg-ink-800/80 dark:text-white">
      <span className="flex h-7 w-7 items-center justify-center rounded-lg bg-gradient-to-br from-brand-600 to-violet-600 text-white">
        <Icon className="h-4 w-4" />
      </span>
      {text}
    </div>
  </motion.div>
);

const Hero: React.FC = () => (
  <section id="home" aria-label="Introduction" className={sectionAnchor}>
    <div className={`relative overflow-hidden ${card}`}>
      <Backdrop />
      <div className="relative grid md:grid-cols-[minmax(0,1fr)_auto] md:items-end">
        <motion.div
          variants={stagger}
          initial="hidden"
          animate="show"
          className="px-6 pt-10 sm:px-10 md:self-center md:py-14 md:pr-4 lg:pl-14"
        >
          <motion.p
            variants={rise}
            className="inline-flex items-center gap-2 rounded-full border border-emerald-200 bg-emerald-50 px-3 py-1 text-xs font-semibold text-emerald-700 dark:border-emerald-500/30 dark:bg-emerald-500/10 dark:text-emerald-300"
          >
            <span className="relative flex h-2 w-2">
              <span className="absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75 motion-safe:animate-ping" />
              <span className="relative inline-flex h-2 w-2 rounded-full bg-emerald-500" />
            </span>
            {portfolio.availability}
          </motion.p>

          <motion.h1
            variants={rise}
            className="mt-5 text-[1.75rem] font-bold leading-tight tracking-tight text-ink-900 dark:text-white sm:text-[2.5rem]"
          >
            I&apos;m {portfolio.name}{' '}
            <span className="sr-only">{portfolio.roles[0]}</span>
            <span className="block min-h-[1.25em]">
              <RotatingText
                items={portfolio.roles}
                className="bg-gradient-to-r from-brand-600 via-violet-600 to-brand-600 bg-[length:200%_auto] bg-clip-text text-transparent motion-safe:animate-gradient-x dark:from-brand-400 dark:via-violet-400 dark:to-brand-400"
              />
            </span>
          </motion.h1>

          <motion.p variants={rise} className="mt-5 max-w-xl leading-relaxed text-slate-600 dark:text-slate-400">
            <span className="font-semibold text-ink-900 dark:text-white">{portfolio.headline}</span> {portfolio.intro}
          </motion.p>

          <motion.div variants={rise} className="mt-8 flex flex-wrap items-center gap-3">
            <a href={portfolio.cvUrl} download={portfolio.cvFileName} className={primaryButton}>
              Download CV
              <ArrowDownTrayIcon className="h-4 w-4 transition-transform group-hover:translate-y-0.5" />
            </a>
            <a href="#contact" className={`group ${secondaryButton}`}>
              Let&apos;s talk
              <ArrowRightIcon className="h-4 w-4 transition-transform group-hover:translate-x-1" />
            </a>
            <span className="inline-flex items-center gap-1.5 text-sm text-slate-500 dark:text-slate-400">
              <MapPinIcon aria-hidden="true" className="h-4 w-4" />
              <span>{portfolio.timezone}</span>
            </span>
          </motion.div>

          <motion.dl
            variants={rise}
            className="mt-10 grid max-w-xl grid-cols-2 gap-y-5 border-t border-slate-200 pt-6 dark:border-white/10 sm:grid-cols-4"
          >
            {portfolio.stats.map((stat) => (
              <div
                key={stat.label}
                className="flex flex-col-reverse sm:border-l sm:border-slate-200 sm:pl-4 sm:first:border-l-0 sm:first:pl-0 dark:sm:border-white/10"
              >
                <dt className="mt-1 text-xs font-medium text-slate-500 dark:text-slate-400">{stat.label}</dt>
                <dd className="text-2xl font-bold tracking-tight text-ink-900 dark:text-white">
                  <CountUp value={stat.value} className="tabular-nums" />
                </dd>
              </div>
            ))}
          </motion.dl>
        </motion.div>

        {/* The cut-out portrait stands on the bottom edge of the card, in front of a gradient arch. */}
        <motion.div
          initial={{ opacity: 0, y: 40 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.9, delay: 0.25, ease: EASE }}
          className="relative mx-auto mt-10 w-60 self-end sm:w-72 md:mr-6 md:mt-0 lg:mr-10 xl:w-[340px]"
        >
          <div
            aria-hidden="true"
            className="absolute inset-x-3 bottom-0 top-12 rounded-t-full bg-gradient-to-b from-brand-200 via-brand-100 to-violet-100 dark:from-brand-500/35 dark:via-brand-500/10 dark:to-violet-500/10"
          />
          <Avatar
            src={portfolio.photo}
            alt={`Portrait of ${portfolio.name}`}
            initials={portfolio.initials}
            className="relative aspect-[640/790] w-full text-5xl"
          />
          {/* Kept inside the portrait column and below the face, so they never cover the copy. */}
          <ProofBadge icon={BuildingLibraryIcon} text="Government-scale systems" className="left-0 top-[69%]" delay={0.9} />
          <ProofBadge icon={SparklesIcon} text="AI online/offline tutor" className="-right-4 top-[52%]" delay={1.1} />
          <ProofBadge icon={AcademicCapIcon} text="5,000+ students" className="bottom-5 right-2" delay={1.3} />
        </motion.div>
      </div>
    </div>
  </section>
);

export default Hero;
