import React from 'react';
import {
  BuildingLibraryIcon,
  CloudIcon,
  CpuChipIcon,
  ShieldCheckIcon,
  SparklesIcon,
  UserGroupIcon,
} from '@heroicons/react/24/outline';
import CountUp from './CountUp';
import SectionHeading from './SectionHeading';
import SpotlightCard from './SpotlightCard';
import { IconComponent, sectionAnchor } from './sections';
import { portfolio, StrengthIcon } from '../../data/portfolio';

const ICONS: Record<StrengthIcon, IconComponent> = {
  building: BuildingLibraryIcon,
  sparkles: SparklesIcon,
  cpu: CpuChipIcon,
  team: UserGroupIcon,
  cloud: CloudIcon,
  shield: ShieldCheckIcon,
};

