import React, { useState } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import SectionHeading from './SectionHeading';
import TechTags from './TechTags';
import { EASE, hoverLift } from './motion';
import { PROJECT_ICONS } from './projectIcons';
import { card, cardHover, sectionAnchor } from './sections';
import { Spotlight, trackSpotlight } from './spotlight';
import { portfolio, ProjectCategory } from '../../data/portfolio';

type Filter = 'all' | ProjectCategory;

// The rest of the work, filterable by sector. Cards animate in and out as the filter changes.
const Projects: React.FC = () => {
  const [filter, setFilter] = useState<Filter>('all');
  const visible = filter === 'all' ? portfolio.projects : portfolio.projects.filter((p) => p.category === filter);

  return (
    <section id="projects" aria-labelledby="projects-title" className={sectionAnchor}>
      <SectionHeading
        id="projects-title"
        eyebrow="More work"
        title="Projects across sectors"
        subtitle="Government, EdTech, SaaS and enterprise systems I have built or contributed to."
      />

      <div role="group" aria-label="Filter projects" className="mb-8 flex flex-wrap justify-center gap-2">
        {portfolio.projectFilters.map((item) => {
          const active = filter === item.id;
          return (
            <button
              key={item.id}
              type="button"
              aria-pressed={active}
              onClick={() => setFilter(item.id)}
              className={`relative isolate rounded-full px-4 py-2 text-sm font-semibold transition-colors ${
                active
                  ? 'text-white'
                  : 'bg-white text-slate-600 ring-1 ring-slate-200 hover:text-ink-900 dark:bg-ink-900 dark:text-slate-300 dark:ring-white/10 dark:hover:text-white'
              }`}
            >
              {active && (
                <motion.span
                  layoutId="project-filter-pill"
                  transition={{ type: 'spring', stiffness: 400, damping: 34 }}
                  className="absolute inset-0 -z-10 rounded-full bg-gradient-to-r from-brand-600 to-violet-600 shadow-brand"
                />
              )}
              {item.label}
            </button>
          );
        })}
      </div>

      <motion.div layout className="grid gap-5 md:grid-cols-2 xl:grid-cols-3">
        <AnimatePresence mode="popLayout" initial={false}>
          {visible.map((project) => {
            const Icon = PROJECT_ICONS[project.icon];
            return (
              <motion.article
                key={project.name}
                layout
                initial={{ opacity: 0, scale: 0.94 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.94 }}
                transition={{ duration: 0.35, ease: EASE }}
                {...hoverLift}
                onMouseMove={trackSpotlight}
                className={`group relative flex flex-col overflow-hidden p-6 ${card} ${cardHover}`}
              >
                <Spotlight />
                <div className="relative flex items-center gap-3">
                  <span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-brand-50 text-brand-600 transition-transform duration-500 group-hover:-rotate-6 group-hover:scale-110 dark:bg-brand-500/10 dark:text-brand-300">
                    <Icon aria-hidden="true" strokeWidth={1.5} className="h-6 w-6" />
                  </span>
                  <span className="text-xs font-semibold uppercase tracking-wide text-slate-500 dark:text-slate-400">
                    {project.type}
                  </span>
                </div>
                <h3 className="relative mt-4 text-lg font-semibold text-ink-900 dark:text-white">{project.name}</h3>
                <p className="relative mt-2 flex-1 text-sm leading-relaxed text-slate-600 dark:text-slate-400">
                  {project.description}
                </p>
                {project.stack && <TechTags label={`${project.name} tech stack`} items={project.stack} />}
              </motion.article>
            );
          })}
        </AnimatePresence>
      </motion.div>
    </section>
  );
};

export default Projects;
