import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import {
  ArrowDownTrayIcon,
  ArrowUpRightIcon,
  CheckIcon,
  ClipboardDocumentIcon,
  EnvelopeIcon,
  MapPinIcon,
} from '@heroicons/react/24/outline';
import BrandIcon from './BrandIcon';
import { reveal } from './motion';
import { primaryButton, sectionAnchor } from './sections';
import { portfolio } from '../../data/portfolio';

const tile =
  'flex items-center gap-3 rounded-2xl border border-white/10 bg-white/5 p-4 text-left backdrop-blur transition-colors';
const tileIcon = 'flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-brand-500/20 text-brand-200';

// Closing call to action on a navy panel, in both light and dark mode.
const Contact: React.FC = () => {
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    if (!copied) return;
    const id = window.setTimeout(() => setCopied(false), 2000);
    return () => window.clearTimeout(id);
  }, [copied]);

  const copyEmail = async () => {
    if (!navigator.clipboard) return;
    try {
      await navigator.clipboard.writeText(portfolio.email);
      setCopied(true);
    } catch {
      // Clipboard access was refused; the mailto link still works.
    }
  };

  return (
    <section id="contact" aria-labelledby="contact-title" className={sectionAnchor}>
      <motion.div {...reveal()} className="relative overflow-hidden rounded-3xl bg-ink-900 px-6 py-14 text-center sm:px-12">
        <div aria-hidden="true" className="pointer-events-none absolute inset-0">
          <div className="absolute inset-0 bg-dot-grid-dark [background-size:22px_22px]" />
          <div className="absolute -left-20 -top-20 h-72 w-72 rounded-full bg-brand-600/30 blur-3xl motion-safe:animate-float" />
          <div className="absolute -bottom-24 -right-16 h-72 w-72 rounded-full bg-violet-600/25 blur-3xl motion-safe:animate-float-delayed" />
        </div>

        <div className="relative">
          <p className="text-xs font-semibold uppercase tracking-[0.2em] text-brand-300">Contact</p>
          <h2 id="contact-title" className="mx-auto mt-2 max-w-2xl text-3xl font-bold tracking-tight text-white sm:text-4xl">
            Hiring for a senior full-stack or AI role?
          </h2>
          <p className="mx-auto mt-3 max-w-xl text-slate-400">
            Let&apos;s talk. I&apos;m open to remote roles and based in Dhaka (GMT+6). Email is the fastest way to reach me.
          </p>

          <div className="mt-8 flex flex-wrap items-center justify-center gap-3">
            <a href={`mailto:${portfolio.email}`} className={`${primaryButton} max-w-full break-all sm:text-base`}>
              <EnvelopeIcon aria-hidden="true" className="h-5 w-5 shrink-0" />
              {portfolio.email}
            </a>
            <button
              type="button"
              onClick={copyEmail}
              aria-label="Copy email address"
              className="relative flex h-12 w-12 items-center justify-center rounded-full border border-white/15 bg-white/5 text-slate-200 transition-colors hover:border-brand-400 hover:text-white"
            >
              {copied ? <CheckIcon className="h-5 w-5 text-emerald-400" /> : <ClipboardDocumentIcon className="h-5 w-5" />}
              <span
                aria-hidden="true"
                className={`pointer-events-none absolute -top-9 whitespace-nowrap rounded-md bg-white px-2 py-1 text-xs font-semibold text-ink-900 transition-opacity ${
                  copied ? 'opacity-100' : 'opacity-0'
                }`}
              >
                Copied!
              </span>
            </button>
            <a
              href={portfolio.cvUrl}
              download={portfolio.cvFileName}
              className="inline-flex items-center gap-2 rounded-full border border-white/15 bg-white/5 px-6 py-3 text-sm font-semibold text-white transition-colors hover:border-brand-400"
            >
              Download CV
              <ArrowDownTrayIcon aria-hidden="true" className="h-4 w-4" />
            </a>
          </div>
          <p role="status" className="sr-only">
            {copied ? 'Email address copied' : ''}
          </p>

          <div className="mx-auto mt-10 grid max-w-3xl gap-4 sm:grid-cols-3">
            <div className={tile}>
              <span className={tileIcon}>
                <MapPinIcon aria-hidden="true" className="h-5 w-5" />
              </span>
              <div>
                <p className="font-medium text-white">{portfolio.location}</p>
                <p className="text-xs text-slate-400">GMT+6 · open to remote</p>
              </div>
            </div>
            {portfolio.socials.map((social) => (
              <a
                key={social.label}
                href={social.url}
                target="_blank"
                rel="noopener noreferrer"
                className={`group ${tile} hover:border-brand-400/50 hover:bg-white/10`}
              >
                <span className={tileIcon}>
                  <BrandIcon name={social.icon} className="h-5 w-5" />
                </span>
                <span className="flex-1 font-medium text-white">{social.label}</span>
                <ArrowUpRightIcon
                  aria-hidden="true"
                  className="h-4 w-4 text-slate-400 transition-transform group-hover:-translate-y-0.5 group-hover:translate-x-0.5 group-hover:text-white"
                />
              </a>
            ))}
          </div>
        </div>
      </motion.div>
    </section>
  );
};

export default Contact;
