// Shared framer-motion settings for the portfolio page.

export const EASE = [0.22, 1, 0.36, 1] as const;

// Fade and rise the first time an element scrolls into view, staggered by `index`.
export const reveal = (index = 0) => ({
  initial: { opacity: 0, y: 28 },
  whileInView: { opacity: 1, y: 0 },
  viewport: { once: true, margin: '-60px' },
  transition: { duration: 0.6, delay: index * 0.08, ease: EASE },
});

// Lift cards on hover. Kept in framer-motion rather than Tailwind because
// framer-motion owns the element's transform once it has animated it.
export const hoverLift = {
  whileHover: { y: -6, transition: { duration: 0.25, ease: EASE } },
};
