import React from 'react';

// Tracks the cursor inside a card so <Spotlight /> can glow under it.
export const trackSpotlight = (event: React.MouseEvent<HTMLElement>) => {
  const rect = event.currentTarget.getBoundingClientRect();
  event.currentTarget.style.setProperty('--spot-x', `${event.clientX - rect.left}px`);
  event.currentTarget.style.setProperty('--spot-y', `${event.clientY - rect.top}px`);
};

// Soft glow that follows the cursor. Needs a `group relative overflow-hidden` parent.
export const Spotlight: React.FC = () => (
  <div
    aria-hidden="true"
    className="pointer-events-none absolute inset-0 opacity-0 transition-opacity duration-300 group-hover:opacity-100 bg-[radial-gradient(420px_circle_at_var(--spot-x,50%)_var(--spot-y,50%),rgba(99,102,241,0.13),transparent_45%)]"
  />
);
