export interface TextPart {
  text: string;
  metric: boolean;
}

// Numbers that start a word: 80%, 5,000+, 4–6, 400+. The word boundary keeps
// digits inside names such as EC2, S3 and ES6+ from matching.
const METRIC = /\b\d[\d,]*(?:–\d+)?[+%]?/g;

// Splits text so the numbers in it can be emphasised.
export const splitMetrics = (text: string): TextPart[] => {
  const parts: TextPart[] = [];
  let last = 0;
  for (const match of Array.from(text.matchAll(METRIC))) {
    const start = match.index ?? 0;
    if (start > last) parts.push({ text: text.slice(last, start), metric: false });
    parts.push({ text: match[0], metric: true });
    last = start + match[0].length;
  }
  if (last < text.length) parts.push({ text: text.slice(last), metric: false });
  return parts;
};
