import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { 
  PlusIcon,
  DocumentTextIcon,
  EyeIcon,
  HeartIcon,
  PencilIcon,
  TrashIcon,
  PhotoIcon,
  TagIcon,
  CalendarIcon
} from '@heroicons/react/24/outline';

interface Project {
  id: string;
  title: string;
  description: string;
  image: string;
  technologies: string[];
  status: 'published' | 'draft' | 'archived';
  views: number;
  likes: number;
  createdAt: string;
  updatedAt: string;
  featured: boolean;
}

const Projects: React.FC = () => {
  const [projects, setProjects] = useState<Project[]>([
    {
      id: '1',
      title: 'E-Commerce Platform',
      description: 'Modern e-commerce solution built with React, Node.js, and MongoDB. Features include user authentication, payment processing, and real-time inventory management.',
      image: '/api/placeholder/400/300',
      technologies: ['React', 'Node.js', 'MongoDB', 'Stripe'],
      status: 'published',
      views: 1250,
      likes: 89,
      createdAt: '2024-01-15',
      updatedAt: '2024-01-20',
      featured: true,
    },
    {
      id: '2',
      title: 'Task Management App',
      description: 'Collaborative task management tool with real-time updates, drag-and-drop functionality, and team collaboration features.',
      image: '/api/placeholder/400/300',
      technologies: ['Vue.js', 'Express', 'Socket.io', 'PostgreSQL'],
      status: 'draft',
      views: 980,
      likes: 67,
      createdAt: '2024-01-10',
      updatedAt: '2024-01-18',
      featured: false,
    },
    {
      id: '3',
      title: 'Weather Dashboard',
      description: 'Beautiful weather application with forecasting features, interactive maps, and location-based weather updates.',
      image: '/api/placeholder/400/300',
      technologies: ['React', 'TypeScript', 'OpenWeather API', 'Chart.js'],
      status: 'published',
      views: 756,
      likes: 45,
      createdAt: '2024-01-05',
      updatedAt: '2024-01-12',
      featured: false,
    },
  ]);

  const [filter, setFilter] = useState<'all' | 'published' | 'draft' | 'archived'>('all');
  const [searchTerm, setSearchTerm] = useState('');

  const filteredProjects = projects.filter(project => {
    const matchesFilter = filter === 'all' || project.status === filter;
    const matchesSearch = project.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         project.description.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesFilter && matchesSearch;
  });

  const handleDeleteProject = (projectId: string) => {
    if (window.confirm('Are you sure you want to delete this project?')) {
      setProjects(projects.filter(p => p.id !== projectId));
    }
  };

  const handleToggleStatus = (projectId: string) => {
    setProjects(projects.map(project => 
      project.id === projectId 
        ? { ...project, status: project.status === 'published' ? 'draft' : 'published' }
        : project
    ));
  };

  const handleToggleFeatured = (projectId: string) => {
    setProjects(projects.map(project => 
      project.id === projectId 
        ? { ...project, featured: !project.featured }
        : project
    ));
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'published':
        return 'bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-300';
      case 'draft':
        return 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900 dark:text-yellow-300';
      case 'archived':
        return 'bg-gray-100 text-gray-700 dark:bg-gray-900 dark:text-gray-300';
      default:
        return 'bg-gray-100 text-gray-700 dark:bg-gray-900 dark:text-gray-300';
    }
  };

  return (
    <div className="min-h-screen bg-neutral-50 dark:bg-neutral-950">
      <div className="container-premium py-8">
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between mb-8">
          <div>
            <h1 className="text-4xl font-bold gradient-text-premium mb-2">
              Portfolio Projects
            </h1>
            <p className="text-neutral-600 dark:text-neutral-400">
              Manage and showcase your amazing work
            </p>
          </div>
          <Link to="/dashboard/projects/new" className="btn-primary mt-4 sm:mt-0">
            <PlusIcon className="w-5 h-5 mr-2" />
            Add Project
          </Link>
        </div>

        {/* Filters and Search */}
        <div className="card-premium mb-8">
          <div className="flex flex-col lg:flex-row gap-4">
            <div className="flex-1">
              <input
                type="text"
                placeholder="Search projects..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="input-field"
              />
            </div>
            <div className="flex space-x-2">
              {(['all', 'published', 'draft', 'archived'] as const).map((status) => (
                <button
                  key={status}
                  onClick={() => setFilter(status)}
                  className={`px-4 py-2 rounded-xl font-medium transition-all duration-300 ${
                    filter === status
                      ? 'bg-primary-600 text-white'
                      : 'bg-neutral-100 text-neutral-700 hover:bg-neutral-200 dark:bg-neutral-800 dark:text-neutral-300 dark:hover:bg-neutral-700'
                  }`}
                >
                  {status.charAt(0).toUpperCase() + status.slice(1)}
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Projects Grid */}
        {filteredProjects.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {filteredProjects.map((project) => (
              <div key={project.id} className="card-premium group relative">
                {project.featured && (
                  <div className="absolute top-4 right-4 z-10">
                    <span className="px-3 py-1 bg-accent-500 text-white text-xs font-semibold rounded-full">
                      Featured
                    </span>
                  </div>
                )}

                <div className="aspect-w-16 aspect-h-9 mb-4 overflow-hidden rounded-2xl">
                  {project.image ? (
                    <img
                      src={project.image}
                      alt={project.title}
                      className="w-full h-48 object-cover group-hover:scale-105 transition-transform duration-300"
                    />
                  ) : (
                    <div className="w-full h-48 bg-neutral-100 dark:bg-neutral-800 flex items-center justify-center">
                      <PhotoIcon className="w-12 h-12 text-neutral-400" />
                    </div>
                  )}
                </div>

                <div className="space-y-4">
                  <div>
                    <h3 className="text-xl font-semibold text-neutral-900 dark:text-neutral-100 mb-2 group-hover:text-primary-600 dark:group-hover:text-primary-400 transition-colors">
                      {project.title}
                    </h3>
                    <p className="text-neutral-600 dark:text-neutral-400 line-clamp-3">
                      {project.description}
                    </p>
                  </div>

                  <div className="flex flex-wrap gap-2">
                    {project.technologies.slice(0, 3).map((tech) => (
                      <span key={tech} className="tech-tag">
                        {tech}
                      </span>
                    ))}
                    {project.technologies.length > 3 && (
                      <span className="tech-tag">
                        +{project.technologies.length - 3}
                      </span>
                    )}
                  </div>

                  <div className="flex items-center justify-between text-sm text-neutral-500 dark:text-neutral-400">
                    <div className="flex items-center space-x-4">
                      <span className="flex items-center">
                        <EyeIcon className="w-4 h-4 mr-1" />
                        {project.views}
                      </span>
                      <span className="flex items-center">
                        <HeartIcon className="w-4 h-4 mr-1" />
                        {project.likes}
                      </span>
                    </div>
                    <span className={`px-2 py-1 rounded-full text-xs font-medium ${getStatusColor(project.status)}`}>
                      {project.status}
                    </span>
                  </div>

                  <div className="flex items-center justify-between pt-4 border-t border-neutral-200 dark:border-neutral-800">
                    <div className="flex space-x-2">
                      <Link
                        to={`/dashboard/projects/${project.id}/edit`}
                        className="p-2 rounded-lg bg-neutral-100 dark:bg-neutral-800 hover:bg-primary-100 dark:hover:bg-primary-900 transition-colors duration-200"
                      >
                        <PencilIcon className="w-4 h-4 text-neutral-600 dark:text-neutral-400" />
                      </Link>
                      <button
                        onClick={() => handleToggleStatus(project.id)}
                        className="p-2 rounded-lg bg-neutral-100 dark:bg-neutral-800 hover:bg-yellow-100 dark:hover:bg-yellow-900 transition-colors duration-200"
                      >
                        <EyeIcon className="w-4 h-4 text-neutral-600 dark:text-neutral-400" />
                      </button>
                      <button
                        onClick={() => handleToggleFeatured(project.id)}
                        className={`p-2 rounded-lg transition-colors duration-200 ${
                          project.featured
                            ? 'bg-accent-100 dark:bg-accent-900 hover:bg-accent-200 dark:hover:bg-accent-800'
                            : 'bg-neutral-100 dark:bg-neutral-800 hover:bg-neutral-200 dark:hover:bg-neutral-700'
                        }`}
                      >
                        <TagIcon className="w-4 h-4 text-neutral-600 dark:text-neutral-400" />
                      </button>
                      <button
                        onClick={() => handleDeleteProject(project.id)}
                        className="p-2 rounded-lg bg-neutral-100 dark:bg-neutral-800 hover:bg-red-100 dark:hover:bg-red-900 transition-colors duration-200"
                      >
                        <TrashIcon className="w-4 h-4 text-neutral-600 dark:text-neutral-400" />
                      </button>
                    </div>
                    <Link
                      to={`/projects/${project.id}`}
                      className="text-primary-600 dark:text-primary-400 hover:text-primary-700 dark:hover:text-primary-300 font-medium text-sm"
                    >
                      View
                    </Link>
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="card-premium text-center py-16">
            <DocumentTextIcon className="w-16 h-16 text-neutral-400 mx-auto mb-4" />
            <h3 className="text-xl font-semibold text-neutral-900 dark:text-neutral-100 mb-2">
              No projects found
            </h3>
            <p className="text-neutral-600 dark:text-neutral-400 mb-6">
              {searchTerm || filter !== 'all' 
                ? 'Try adjusting your search or filters'
                : 'Start building your portfolio by adding your first project'
              }
            </p>
            {!searchTerm && filter === 'all' && (
              <Link to="/dashboard/projects/new" className="btn-primary">
                <PlusIcon className="w-5 h-5 mr-2" />
                Add Your First Project
              </Link>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default Projects;
