export interface Metric {
  value: string;
  label: string;
}

export type Stat = Metric;

export interface SocialLink {
  label: string;
  url: string;
  icon: 'linkedin' | 'github';
}

export interface InfoRow {
  label: string;
  value: string;
  highlight?: boolean;
}

export interface LanguageSkill {
  name: string;
  level: string;
}

export interface Organization {
  name: string;
  // Spelled out for recruiters outside Bangladesh.
  full?: string;
}

export type StrengthIcon = 'building' | 'sparkles' | 'cpu' | 'team' | 'cloud' | 'shield';

export interface Strength {
  title: string;
  description: string;
  metric: Metric;
  icon: StrengthIcon;
  // Spans two columns in the bento grid.
  wide?: boolean;
  // Drawn as the dark, highlighted tile.
  featured?: boolean;
}

export type ProjectIcon =
  | 'ai'
  | 'book'
  | 'briefcase'
  | 'classroom'
  | 'factory'
  | 'home'
  | 'inventory'
  | 'lab'
  | 'network'
  | 'results'
  | 'scale'
  | 'teacher';

export interface CaseStudy {
  name: string;
  client: string;
  type: string;
  status?: string;
  challenge: string;
  built: string[];
  impact: Metric[];
  stack?: string[];
  icon: ProjectIcon;
}

export type ProjectCategory = 'government' | 'ai-edtech' | 'saas' | 'enterprise';

export interface Project {
  name: string;
  category: ProjectCategory;
  type: string;
  description: string;
  icon: ProjectIcon;
  stack?: string[];
}

export interface SkillGroup {
  name: string;
  items: string[];
}

export interface Job {
  company: string;
  role: string;
  location: string;
  start: number;
  end: number | null;
  highlights: string[];
  stack: string[];
}

export interface EducationEntry {
  degree: string;
  institution: string;
  location: string;
  start: number;
  end: number;
}

export interface Publication {
  title: string;
  description: string;
}

