import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { ThemeProvider } from './contexts/ThemeContext';
import { AuthProvider } from './contexts/AuthContext';
import ProtectedRoute from './components/Auth/ProtectedRoute';
import Layout from './components/Layout/Layout';
// Public pages
import PortfolioHome from './pages/PortfolioHome';
import About from './pages/About';
import Projects from './pages/Projects';
import Blog from './pages/Blog';
import Contact from './pages/Contact';
import Login from './pages/Login';
import Register from './pages/Register';
// Dashboard pages
import Dashboard from './pages/Dashboard';
import Profile from './pages/Dashboard/Profile';
import DashboardProjects from './pages/Dashboard/Projects';
import Resume from './pages/Dashboard/Resume';
import CreateProject from './pages/Dashboard/CreateProject';

// Create a client
const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      retry: 1,
      refetchOnWindowFocus: false,
    },
  },
});

function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <ThemeProvider>
        <AuthProvider>
          <Router>
            <Routes>
              {/* Public routes */}
              <Route path="/" element={<PortfolioHome />} />
              <Route path="/about" element={<Layout><About /></Layout>} />
              <Route path="/projects" element={<Layout><Projects /></Layout>} />
              <Route path="/blog" element={<Layout><Blog /></Layout>} />
              <Route path="/contact" element={<Layout><Contact /></Layout>} />
              
              {/* Auth routes */}
              <Route path="/login" element={<Login />} />
              <Route path="/register" element={<Register />} />
              
              {/* Protected dashboard routes */}
              <Route path="/dashboard" element={
                <ProtectedRoute>
                  <Dashboard />
                </ProtectedRoute>
              } />
              <Route path="/dashboard/profile" element={
                <ProtectedRoute>
                  <Profile />
                </ProtectedRoute>
              } />
              <Route path="/dashboard/projects" element={
                <ProtectedRoute>
                  <DashboardProjects />
                </ProtectedRoute>
              } />
              <Route path="/dashboard/resume" element={
                <ProtectedRoute>
                  <Resume />
                </ProtectedRoute>
              } />
              <Route path="/dashboard/projects/new" element={
                <ProtectedRoute>
                  <CreateProject />
                </ProtectedRoute>
              } />
              
              {/* Placeholder routes for future development */}
              <Route path="/dashboard/media" element={
                <ProtectedRoute>
                  <div className="min-h-screen flex items-center justify-center">
                    <div className="text-center">
                      <h1 className="text-4xl font-bold gradient-text-premium mb-4">Media Gallery</h1>
                      <p className="text-neutral-600 dark:text-neutral-400">Coming Soon - Manage your media files</p>
                    </div>
                  </div>
                </ProtectedRoute>
              } />
              <Route path="/dashboard/analytics" element={
                <ProtectedRoute>
                  <div className="min-h-screen flex items-center justify-center">
                    <div className="text-center">
                      <h1 className="text-4xl font-bold gradient-text-premium mb-4">Analytics</h1>
                      <p className="text-neutral-600 dark:text-neutral-400">Coming Soon - View your portfolio statistics</p>
                    </div>
                  </div>
                </ProtectedRoute>
              } />
              <Route path="/dashboard/settings" element={
                <ProtectedRoute>
                  <div className="min-h-screen flex items-center justify-center">
                    <div className="text-center">
                      <h1 className="text-4xl font-bold gradient-text-premium mb-4">Settings</h1>
                      <p className="text-neutral-600 dark:text-neutral-400">Coming Soon - Manage your account settings</p>
                    </div>
                  </div>
                </ProtectedRoute>
              } />
              
              {/* Blog post detail route */}
              <Route path="/blog/:slug" element={
                <Layout>
                  <div className="min-h-screen flex items-center justify-center">
                    <div className="text-center">
                      <h1 className="text-4xl font-bold gradient-text-premium mb-4">Blog Post Detail</h1>
                      <p className="text-neutral-600 dark:text-neutral-400">Coming Soon</p>
                    </div>
                  </div>
                </Layout>
              } />
              
              {/* Project detail route */}
              <Route path="/projects/:slug" element={
                <Layout>
                  <div className="min-h-screen flex items-center justify-center">
                    <div className="text-center">
                      <h1 className="text-4xl font-bold gradient-text-premium mb-4">Project Detail</h1>
                      <p className="text-neutral-600 dark:text-neutral-400">Coming Soon</p>
                    </div>
                  </div>
                </Layout>
              } />
              
              {/* Fallback route */}
              <Route path="*" element={<Navigate to="/" replace />} />
            </Routes>
          </Router>
        </AuthProvider>
      </ThemeProvider>
    </QueryClientProvider>
  );
}

export default App;
