import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import { 
  UserIcon,
  BriefcaseIcon,
  AcademicCapIcon,
  HeartIcon,
  CodeBracketIcon,
  SparklesIcon
} from '@heroicons/react/24/outline';
import apiService, { Profile } from '../services/api';

const About: React.FC = () => {
  const [profile, setProfile] = useState<Profile | null>(null);
  const [experiences, setExperiences] = useState<any[]>([]);
  const [education, setEducation] = useState<any[]>([]);
  const [skills, setSkills] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [profileRes, expRes, eduRes, skillsRes] = await Promise.all([
          apiService.getProfile(),
          apiService.getExperiences(),
          apiService.getEducation(),
          apiService.getSkills()
        ]);

        setProfile(profileRes.data);
        setExperiences(expRes.data || []);
        setEducation(eduRes.data || []);
        setSkills(skillsRes.data.data || []);
      } catch (error) {
        console.error('Error fetching data:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
      </div>
    );
  }

  return (
    <div className="space-y-20">
      {/* Hero Section */}
      <section className="section-padding hero-gradient">
        <div className="container-max">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6 }}
            className="text-center"
          >
            <div className="w-24 h-24 mx-auto mb-6 bg-gradient-to-br from-primary-600 to-purple-600 rounded-full flex items-center justify-center">
              <UserIcon className="w-12 h-12 text-white" />
            </div>
            <h1 className="text-4xl sm:text-5xl font-bold mb-6">
              <span className="gradient-text">About Me</span>
            </h1>
            <p className="text-xl text-gray-600 dark:text-gray-300 mb-8 max-w-3xl mx-auto text-balance">
              Passionate developer crafting digital experiences with modern technologies
            </p>
          </motion.div>
        </div>
      </section>

      {/* Profile Summary */}
      <section className="section-padding">
        <div className="container-max">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 items-center">
            <motion.div
              initial={{ opacity: 0, x: -20 }}
              whileInView={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.6 }}
              viewport={{ once: true }}
            >
              <h2 className="text-3xl font-bold mb-6 gradient-text">Who I Am</h2>
              <div className="prose prose-lg dark:prose-invert max-w-none">
                <p className="text-gray-600 dark:text-gray-300 leading-relaxed mb-4">
                  {profile?.professional_summary || profile?.bio}
                </p>
                <div className="grid grid-cols-2 gap-4 mt-6">
                  <div className="flex items-center space-x-3">
                    <BriefcaseIcon className="w-5 h-5 text-primary-600" />
                    <span className="text-gray-700 dark:text-gray-300">
                      {profile?.years_of_experience}+ Years Experience
                    </span>
                  </div>
                  <div className="flex items-center space-x-3">
                    <CodeBracketIcon className="w-5 h-5 text-primary-600" />
                    <span className="text-gray-700 dark:text-gray-300">
                      {profile?.projects_completed}+ Projects
                    </span>
                  </div>
                  <div className="flex items-center space-x-3">
                    <HeartIcon className="w-5 h-5 text-primary-600" />
                    <span className="text-gray-700 dark:text-gray-300">
                      {profile?.happy_clients}+ Happy Clients
                    </span>
                  </div>
                  <div className="flex items-center space-x-3">
                    <SparklesIcon className="w-5 h-5 text-primary-600" />
                    <span className="text-gray-700 dark:text-gray-300">
                      {skills.length}+ Technologies
                    </span>
                  </div>
                </div>
              </div>
            </motion.div>

            <motion.div
              initial={{ opacity: 0, x: 20 }}
              whileInView={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.6 }}
              viewport={{ once: true }}
              className="space-y-6"
            >
              <div className="card">
                <h3 className="text-xl font-semibold mb-4 flex items-center">
                  <UserIcon className="w-6 h-6 mr-3 text-primary-600" />
                  Personal Info
                </h3>
                <div className="space-y-3">
                  <div>
                    <span className="text-sm text-gray-500 dark:text-gray-400">Name</span>
                    <p className="font-medium">{profile?.full_name}</p>
                  </div>
                  <div>
                    <span className="text-sm text-gray-500 dark:text-gray-400">Title</span>
                    <p className="font-medium">{profile?.title}</p>
                  </div>
                  <div>
                    <span className="text-sm text-gray-500 dark:text-gray-400">Location</span>
                    <p className="font-medium">{profile?.location}</p>
                  </div>
                  <div>
                    <span className="text-sm text-gray-500 dark:text-gray-400">Email</span>
                    <p className="font-medium">{profile?.email}</p>
                  </div>
                </div>
              </div>

              <div className="card">
                <h3 className="text-xl font-semibold mb-4">Availability</h3>
                <div className="flex items-center justify-between">
                  <span className="text-gray-600 dark:text-gray-400">Available for work</span>
                  <span className={`px-3 py-1 rounded-full text-sm font-medium ${
                    profile?.is_available_for_work 
                      ? 'bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-300'
                      : 'bg-gray-100 text-gray-700 dark:bg-gray-700 dark:text-gray-300'
                  }`}>
                    {profile?.is_available_for_work ? 'Available' : 'Not Available'}
                  </span>
                </div>
                {profile?.availability_status && (
                  <p className="text-sm text-gray-600 dark:text-gray-400 mt-2">
                    {profile.availability_status}
                  </p>
                )}
              </div>
            </motion.div>
          </div>
        </div>
      </section>

      {/* Experience */}
      <section className="section-padding bg-gray-50 dark:bg-gray-900">
        <div className="container-max">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6 }}
            viewport={{ once: true }}
            className="text-center mb-12"
          >
            <h2 className="text-3xl sm:text-4xl font-bold mb-4 gradient-text">Experience</h2>
            <p className="text-lg text-gray-600 dark:text-gray-400 max-w-2xl mx-auto">
              My professional journey and achievements
            </p>
          </motion.div>

          <div className="space-y-8">
            {experiences.map((exp, index) => (
              <motion.div
                key={exp.id}
                initial={{ opacity: 0, x: -20 }}
                whileInView={{ opacity: 1, x: 0 }}
                transition={{ duration: 0.4, delay: index * 0.1 }}
                viewport={{ once: true }}
                className="card"
              >
                <div className="flex flex-col md:flex-row md:items-start md:space-x-6">
                  <div className="flex-shrink-0 mb-4 md:mb-0">
                    <div className="w-12 h-12 bg-gradient-to-br from-primary-600 to-purple-600 rounded-lg flex items-center justify-center">
                      <BriefcaseIcon className="w-6 h-6 text-white" />
                    </div>
                  </div>
                  <div className="flex-grow">
                    <h3 className="text-xl font-semibold mb-2">{exp.title}</h3>
                    <p className="text-primary-600 dark:text-primary-400 font-medium mb-2">
                      {exp.company}
                    </p>
                    <p className="text-sm text-gray-500 dark:text-gray-400 mb-4">
                      {exp.start_date} - {exp.end_date || 'Present'}
                    </p>
                    <p className="text-gray-600 dark:text-gray-300">
                      {exp.description}
                    </p>
                    {exp.achievements && exp.achievements.length > 0 && (
                      <ul className="mt-4 space-y-2">
                        {exp.achievements.map((achievement: string, i: number) => (
                          <li key={i} className="flex items-start">
                            <span className="text-primary-600 mr-2">•</span>
                            <span className="text-gray-600 dark:text-gray-300">{achievement}</span>
                          </li>
                        ))}
                      </ul>
                    )}
                  </div>
                </div>
              </motion.div>
            ))}
          </div>
        </div>
      </section>

      {/* Education */}
      <section className="section-padding">
        <div className="container-max">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6 }}
            viewport={{ once: true }}
            className="text-center mb-12"
          >
            <h2 className="text-3xl sm:text-4xl font-bold mb-4 gradient-text">Education</h2>
            <p className="text-lg text-gray-600 dark:text-gray-400 max-w-2xl mx-auto">
              Academic background and qualifications
            </p>
          </motion.div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            {education.map((edu, index) => (
              <motion.div
                key={edu.id}
                initial={{ opacity: 0, scale: 0.9 }}
                whileInView={{ opacity: 1, scale: 1 }}
                transition={{ duration: 0.4, delay: index * 0.1 }}
                viewport={{ once: true }}
                className="card"
              >
                <div className="flex items-start space-x-4">
                  <div className="flex-shrink-0">
                    <div className="w-12 h-12 bg-gradient-to-br from-primary-600 to-purple-600 rounded-lg flex items-center justify-center">
                      <AcademicCapIcon className="w-6 h-6 text-white" />
                    </div>
                  </div>
                  <div>
                    <h3 className="text-xl font-semibold mb-2">{edu.degree}</h3>
                    <p className="text-primary-600 dark:text-primary-400 font-medium mb-2">
                      {edu.institution}
                    </p>
                    <p className="text-sm text-gray-500 dark:text-gray-400 mb-2">
                      {edu.start_date} - {edu.end_date}
                    </p>
                    {edu.field_of_study && (
                      <p className="text-gray-600 dark:text-gray-300">
                        Field: {edu.field_of_study}
                      </p>
                    )}
                    {edu.gpa && (
                      <p className="text-gray-600 dark:text-gray-300">
                        GPA: {edu.gpa}
                      </p>
                    )}
                  </div>
                </div>
              </motion.div>
            ))}
          </div>
        </div>
      </section>

      {/* Skills Overview */}
      <section className="section-padding bg-gray-50 dark:bg-gray-900">
        <div className="container-max">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6 }}
            viewport={{ once: true }}
            className="text-center mb-12"
          >
            <h2 className="text-3xl sm:text-4xl font-bold mb-4 gradient-text">Core Skills</h2>
            <p className="text-lg text-gray-600 dark:text-gray-400 max-w-2xl mx-auto">
              Technologies and expertise I bring to every project
            </p>
          </motion.div>

          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
            {skills.slice(0, 12).map((skill, index) => (
              <motion.div
                key={skill.id}
                initial={{ opacity: 0, scale: 0.9 }}
                whileInView={{ opacity: 1, scale: 1 }}
                transition={{ duration: 0.4, delay: index * 0.05 }}
                viewport={{ once: true }}
                className="text-center"
              >
                <div
                  className="w-16 h-16 mx-auto mb-3 rounded-xl flex items-center justify-center"
                  style={{ backgroundColor: skill.color + '20' }}
                >
                  <div
                    className="w-8 h-8 rounded-lg"
                    style={{ backgroundColor: skill.color }}
                  ></div>
                </div>
                <h4 className="font-medium text-sm">{skill.name}</h4>
                <div className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                  {skill.category}
                </div>
              </motion.div>
            ))}
          </div>
        </div>
      </section>
    </div>
  );
};

export default About;
