import React, { useState, useRef } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { 
  UserIcon, 
  CameraIcon,
  EnvelopeIcon,
  PhoneIcon,
  MapPinIcon,
  BriefcaseIcon,
  AcademicCapIcon,
  GlobeAltIcon,
  CodeBracketIcon,
  BuildingOfficeIcon,
  ChatBubbleLeftRightIcon
} from '@heroicons/react/24/outline';

const Profile: React.FC = () => {
  const { user, updateProfile } = useAuth();
  const [isEditing, setIsEditing] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [previewImage, setPreviewImage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    name: user?.name || '',
    email: user?.email || '',
    bio: '',
    title: '',
    location: '',
    phone: '',
    website: '',
    github: '',
    linkedin: '',
    twitter: '',
    experience: '',
    education: '',
  });

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreviewImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      await updateProfile(formData);
      setIsEditing(false);
    } catch (error) {
      console.error('Profile update failed:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const socialLinks = [
    { name: 'github', icon: CodeBracketIcon, placeholder: 'github.com/username' },
    { name: 'linkedin', icon: BuildingOfficeIcon, placeholder: 'linkedin.com/in/username' },
    { name: 'twitter', icon: ChatBubbleLeftRightIcon, placeholder: 'twitter.com/username' },
  ];

  return (
    <div className="min-h-screen bg-neutral-50 dark:bg-neutral-950">
      <div className="container-premium py-8">
        <div className="mb-8">
          <h1 className="text-4xl font-bold gradient-text-premium mb-2">
            Profile Management
          </h1>
          <p className="text-neutral-600 dark:text-neutral-400">
            Update your personal information and professional details
          </p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Profile Card */}
          <div className="lg:col-span-1">
            <div className="card-premium">
              <div className="text-center">
                <div className="relative inline-block">
                  <div className="w-32 h-32 bg-gradient-to-br from-primary-500 to-secondary-500 rounded-full mx-auto mb-4 flex items-center justify-center">
                    {previewImage ? (
                      <img
                        src={previewImage}
                        alt="Profile"
                        className="w-full h-full rounded-full object-cover"
                      />
                    ) : (
                      <UserIcon className="w-16 h-16 text-white" />
                    )}
                  </div>
                  <button
                    onClick={() => fileInputRef.current?.click()}
                    className="absolute bottom-4 right-0 w-10 h-10 bg-primary-600 text-white rounded-full flex items-center justify-center shadow-medium hover:shadow-strong transition-all duration-300 transform hover:scale-110"
                  >
                    <CameraIcon className="w-5 h-5" />
                  </button>
                  <input
                    ref={fileInputRef}
                    type="file"
                    accept="image/*"
                    onChange={handleImageUpload}
                    className="hidden"
                  />
                </div>

                <h2 className="text-2xl font-bold text-neutral-900 dark:text-neutral-100 mb-2">
                  {formData.name || 'Your Name'}
                </h2>
                <p className="text-neutral-600 dark:text-neutral-400 mb-4">
                  {formData.title || 'Your Title'}
                </p>

                <div className="flex items-center justify-center space-x-2 text-sm text-neutral-500 dark:text-neutral-400 mb-6">
                  <MapPinIcon className="w-4 h-4" />
                  <span>{formData.location || 'Location'}</span>
                </div>

                <div className="flex space-x-3">
                  {socialLinks.map((social) => {
                    const Icon = social.icon;
                    const url = formData[social.name as keyof typeof formData];
                    return url ? (
                      <a
                        key={social.name}
                        href={`https://${url}`}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="w-10 h-10 bg-neutral-100 dark:bg-neutral-800 rounded-full flex items-center justify-center hover:bg-primary-100 dark:hover:bg-primary-900 transition-colors duration-300"
                      >
                        <Icon className="w-5 h-5 text-neutral-600 dark:text-neutral-400" />
                      </a>
                    ) : null;
                  })}
                </div>
              </div>
            </div>
          </div>

          {/* Form Section */}
          <div className="lg:col-span-2">
            <div className="card-premium">
              <div className="flex items-center justify-between mb-6">
                <h3 className="text-xl font-semibold text-neutral-900 dark:text-neutral-100">
                  Personal Information
                </h3>
                <button
                  onClick={() => setIsEditing(!isEditing)}
                  className={`px-4 py-2 rounded-xl font-medium transition-all duration-300 ${
                    isEditing
                      ? 'bg-red-100 text-red-700 dark:bg-red-900 dark:text-red-300'
                      : 'bg-primary-100 text-primary-700 dark:bg-primary-900 dark:text-primary-300'
                  }`}
                >
                  {isEditing ? 'Cancel' : 'Edit Profile'}
                </button>
              </div>

              {isEditing ? (
                <form onSubmit={handleSubmit} className="space-y-6">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                      <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-2">
                        Full Name
                      </label>
                      <input
                        type="text"
                        name="name"
                        value={formData.name}
                        onChange={handleChange}
                        className="input-field"
                        placeholder="John Doe"
                      />
                    </div>

                    <div>
                      <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-2">
                        Email Address
                      </label>
                      <input
                        type="email"
                        name="email"
                        value={formData.email}
                        onChange={handleChange}
                        className="input-field"
                        placeholder="john@example.com"
                      />
                    </div>

                    <div>
                      <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-2">
                        Professional Title
                      </label>
                      <input
                        type="text"
                        name="title"
                        value={formData.title}
                        onChange={handleChange}
                        className="input-field"
                        placeholder="Full Stack Developer"
                      />
                    </div>

                    <div>
                      <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-2">
                        Location
                      </label>
                      <input
                        type="text"
                        name="location"
                        value={formData.location}
                        onChange={handleChange}
                        className="input-field"
                        placeholder="San Francisco, CA"
                      />
                    </div>

                    <div>
                      <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-2">
                        Phone Number
                      </label>
                      <input
                        type="tel"
                        name="phone"
                        value={formData.phone}
                        onChange={handleChange}
                        className="input-field"
                        placeholder="+1 (555) 123-4567"
                      />
                    </div>

                    <div>
                      <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-2">
                        Website
                      </label>
                      <input
                        type="url"
                        name="website"
                        value={formData.website}
                        onChange={handleChange}
                        className="input-field"
                        placeholder="https://yourwebsite.com"
                      />
                    </div>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-2">
                      Bio
                    </label>
                    <textarea
                      name="bio"
                      value={formData.bio}
                      onChange={handleChange}
                      rows={4}
                      className="textarea-field"
                      placeholder="Tell us about yourself and your professional journey..."
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-2">
                      Experience
                    </label>
                    <textarea
                      name="experience"
                      value={formData.experience}
                      onChange={handleChange}
                      rows={3}
                      className="textarea-field"
                      placeholder="Describe your professional experience..."
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-2">
                      Education
                    </label>
                    <textarea
                      name="education"
                      value={formData.education}
                      onChange={handleChange}
                      rows={3}
                      className="textarea-field"
                      placeholder="Your educational background..."
                    />
                  </div>

                  <div>
                    <h4 className="text-lg font-medium text-neutral-900 dark:text-neutral-100 mb-4">
                      Social Profiles
                    </h4>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                      {socialLinks.map((social) => {
                        const Icon = social.icon;
                        return (
                          <div key={social.name} className="relative">
                            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                              <Icon className="h-5 w-5 text-neutral-400" />
                            </div>
                            <input
                              type="text"
                              name={social.name}
                              value={formData[social.name as keyof typeof formData]}
                              onChange={handleChange}
                              className="input-field pl-10"
                              placeholder={social.placeholder}
                            />
                          </div>
                        );
                      })}
                    </div>
                  </div>

                  <div className="flex space-x-4">
                    <button
                      type="submit"
                      disabled={isLoading}
                      className="btn-primary"
                    >
                      {isLoading ? 'Saving...' : 'Save Changes'}
                    </button>
                    <button
                      type="button"
                      onClick={() => setIsEditing(false)}
                      className="btn-secondary"
                    >
                      Cancel
                    </button>
                  </div>
                </form>
              ) : (
                <div className="space-y-6">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                      <h4 className="text-sm font-medium text-neutral-500 dark:text-neutral-400 mb-1">
                        Email
                      </h4>
                      <div className="flex items-center text-neutral-900 dark:text-neutral-100">
                        <EnvelopeIcon className="w-4 h-4 mr-2 text-neutral-400" />
                        {formData.email || 'Not provided'}
                      </div>
                    </div>

                    <div>
                      <h4 className="text-sm font-medium text-neutral-500 dark:text-neutral-400 mb-1">
                        Phone
                      </h4>
                      <div className="flex items-center text-neutral-900 dark:text-neutral-100">
                        <PhoneIcon className="w-4 h-4 mr-2 text-neutral-400" />
                        {formData.phone || 'Not provided'}
                      </div>
                    </div>

                    <div>
                      <h4 className="text-sm font-medium text-neutral-500 dark:text-neutral-400 mb-1">
                        Location
                      </h4>
                      <div className="flex items-center text-neutral-900 dark:text-neutral-100">
                        <MapPinIcon className="w-4 h-4 mr-2 text-neutral-400" />
                        {formData.location || 'Not provided'}
                      </div>
                    </div>

                    <div>
                      <h4 className="text-sm font-medium text-neutral-500 dark:text-neutral-400 mb-1">
                        Website
                      </h4>
                      <div className="flex items-center text-neutral-900 dark:text-neutral-100">
                        <GlobeAltIcon className="w-4 h-4 mr-2 text-neutral-400" />
                        {formData.website ? (
                          <a
                            href={formData.website}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="text-primary-600 dark:text-primary-400 hover:underline"
                          >
                            {formData.website}
                          </a>
                        ) : (
                          'Not provided'
                        )}
                      </div>
                    </div>
                  </div>

                  {formData.bio && (
                    <div>
                      <h4 className="text-sm font-medium text-neutral-500 dark:text-neutral-400 mb-2">
                        Bio
                      </h4>
                      <p className="text-neutral-900 dark:text-neutral-100">
                        {formData.bio}
                      </p>
                    </div>
                  )}

                  {formData.experience && (
                    <div>
                      <h4 className="text-sm font-medium text-neutral-500 dark:text-neutral-400 mb-2">
                        Experience
                      </h4>
                      <p className="text-neutral-900 dark:text-neutral-100">
                        {formData.experience}
                      </p>
                    </div>
                  )}

                  {formData.education && (
                    <div>
                      <h4 className="text-sm font-medium text-neutral-500 dark:text-neutral-400 mb-2">
                        Education
                      </h4>
                      <p className="text-neutral-900 dark:text-neutral-100">
                        {formData.education}
                      </p>
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Profile;
