import React, { useEffect, useRef, useState } from 'react';
import { animate, useInView, useReducedMotion } from 'framer-motion';
import { EASE } from './motion';

export interface ParsedCount {
  value: number;
  suffix: string;
}

// "5,000+" -> { value: 5000, suffix: '+' }. Returns null for anything that isn't
// one number followed by non-digits, such as the range "4–6".
export const parseCount = (text: string): ParsedCount | null => {
  const match = /^(\d{1,3}(?:,\d{3})+|\d+)(\D*)$/.exec(text);
  return match ? { value: Number(match[1].replace(/,/g, '')), suffix: match[2] } : null;
};

export const formatCount = (value: number): string => value.toLocaleString('en-US');

// Counts up from zero the first time it scrolls into view. Screen readers get
// the final value straight away.
const CountUp: React.FC<{ value: string; className?: string }> = ({ value, className = '' }) => {
  const parsed = parseCount(value);
  const target = parsed?.value;
  const ref = useRef<HTMLSpanElement>(null);
  const inView = useInView(ref, { once: true });
  const reduceMotion = useReducedMotion();
  const [current, setCurrent] = useState(0);

  useEffect(() => {
    if (target === undefined || !inView) return;
    if (reduceMotion) {
      setCurrent(target);
      return;
    }
    const controls = animate(0, target, {
      duration: 1.6,
      ease: EASE,
      onUpdate: (latest) => setCurrent(Math.round(latest)),
    });
    return () => controls.stop();
  }, [target, inView, reduceMotion]);

  if (!parsed) return <span className={className}>{value}</span>;

  return (
    <span ref={ref} className={className}>
      <span className="sr-only">{value}</span>
      <span aria-hidden="true">
        {formatCount(current)}
        {parsed.suffix}
      </span>
    </span>
  );
};

export default CountUp;
