import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import {
  AcademicCapIcon,
  BriefcaseIcon,
  CpuChipIcon,
  EnvelopeIcon,
  HomeIcon,
  MoonIcon,
  RectangleStackIcon,
  StarIcon,
  SunIcon,
} from '@heroicons/react/24/outline';
import { useTheme } from '../../contexts/ThemeContext';
import { IconComponent, SECTIONS, SectionId } from './sections';

const ICONS: Record<SectionId, IconComponent> = {
  home: HomeIcon,
  strengths: StarIcon,
  work: RectangleStackIcon,
  experience: BriefcaseIcon,
  skills: CpuChipIcon,
  education: AcademicCapIcon,
  contact: EnvelopeIcon,
};

const button = 'flex h-10 w-10 items-center justify-center rounded-full transition-colors';
const idle =
  'text-slate-400 hover:bg-slate-100 hover:text-ink-900 dark:text-slate-500 dark:hover:bg-white/10 dark:hover:text-white';

// Right-hand icon rail on desktop, bottom bar on small screens.
const NavRail: React.FC = () => {
  const { theme, toggleTheme } = useTheme();
  const [active, setActive] = useState<SectionId>('home');

  // Highlight whichever section is crossing the middle of the viewport.
  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) setActive(entry.target.id as SectionId);
        });
      },
      { rootMargin: '-45% 0px -50% 0px' }
    );
    SECTIONS.forEach(({ id }) => {
      const element = document.getElementById(id);
      if (element) observer.observe(element);
    });
    return () => observer.disconnect();
  }, []);

  const isDark = theme === 'dark';

  return (
    <nav
      aria-label="Sections"
      className="fixed inset-x-0 bottom-0 z-20 flex items-center justify-around border-t border-slate-200 bg-white/90 px-2 py-2 backdrop-blur dark:border-white/10 dark:bg-ink-900/90 lg:inset-x-auto lg:inset-y-0 lg:right-0 lg:w-[88px] lg:flex-col lg:justify-start lg:gap-3 lg:border-l lg:border-t-0 lg:py-8"
    >
      <button
        type="button"
        onClick={toggleTheme}
        aria-label={isDark ? 'Switch to light mode' : 'Switch to dark mode'}
        className={`${button} bg-ink-900 text-white hover:bg-ink-700 dark:bg-white dark:text-ink-900 dark:hover:bg-slate-200 lg:mb-10`}
      >
        {isDark ? <SunIcon className="h-5 w-5" /> : <MoonIcon className="h-5 w-5" />}
      </button>
      {SECTIONS.map(({ id, label }) => {
        const Icon = ICONS[id];
        const isActive = active === id;
        return (
          <a
            key={id}
            href={`#${id}`}
            aria-label={label}
            aria-current={isActive ? 'true' : undefined}
            onClick={() => setActive(id)}
            className={`group relative ${button} ${isActive ? 'text-white' : idle}`}
          >
            {/* One shared pill that slides to whichever link is active. */}
            {isActive && (
              <motion.span
                layoutId="nav-active-pill"
                transition={{ type: 'spring', stiffness: 400, damping: 32 }}
                className="absolute inset-0 rounded-full bg-gradient-to-br from-brand-600 to-violet-600 shadow-brand"
              />
            )}
            <Icon aria-hidden="true" className="relative h-5 w-5" />
            <span
              aria-hidden="true"
              className="pointer-events-none absolute right-full mr-3 hidden whitespace-nowrap rounded-md bg-ink-900 px-2 py-1 text-xs font-medium text-white opacity-0 transition-opacity group-hover:opacity-100 group-focus-visible:opacity-100 dark:bg-white dark:text-ink-900 lg:block"
            >
              {label}
            </span>
          </a>
        );
      })}
    </nav>
  );
};

export default NavRail;
